{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Phytoene was estimated to be 58.5% absorbed in humans, which is above the 20% threshold, but this result has limited transferability to the query because phytoene is a nonpolar hydrocarbon carotenoid, whereas the query is a high-molecular-weight ubiquinone with a polar quinone head and a long decaprenyl tail.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Mulberroside A showed low oral bioavailability in humans, but the reported mechanism is rapid intestinal deglycosylation of a glycoside, which is not applicable to the non-glycosidic ubiquinone query; this provides only weak supportive evidence for low bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is ubiquinone-10, a large, extremely lipophilic, poorly water-soluble molecule. The only high-F evidence (phytoene) is structurally distant and not mechanistically transferable, while the low-F evidence (mulberroside A) is mechanistically irrelevant. The query's absorption limitations support F <20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or a close ubiquinone analogue.",
    "Retrieved analogues have low Morgan similarity (<0.4) and differ substantially in polarity, size, and absorption mechanism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

